for f in select id,stable_code from public.food_items where owner_id is null and stable_code is not null loop
 encoded:=replace(encoded,to_json('catalog:'||f.stable_code)::text,to_json(f.id::text)::text);
end loop;
if position('"catalog:' in encoded)>0 then raise exception 'Falta un alimento del catálogo requerido por la importación'; end if;
with seed as (select encoded::jsonb as c), expanded as (select jsonb_set(jsonb_set(c,'{menu,menus,0,meal_menus}',(select jsonb_agg(jsonb_build_object('meal_time_id',o->'meal_time_id','entries',o->'entries')) from jsonb_array_elements(c#>'{menu,meal_options}') o)),'{menu,week_plan,days,0,assignments}',(select jsonb_agg(jsonb_build_object('meal_time_id',o->'meal_time_id','option_id',o->'id','option_snapshot',o,'fixed',false)) from jsonb_array_elements(c#>'{menu,meal_options}') o)) as content from seed) insert into public.diet_library_items(owner_id,name,content,provenance) select null,'PDF11-D2 · Tostadas con huevo y frijoles',content,'{"kind":"provided_pdf","label":"Documento aportado · PDF11-D2 · página 3","declared_energy":"1,800–1,900 kcal al día","target_basis":"El documento no declara una distribución completa de macros. Falta verificar ingredientes antes de calcular el total y proponer objetivos.","notes":["Dieta de un día reutilizable; las etapas de varios días no se convirtieron en un calendario semanal.","Las cantidades domésticas explícitas se conservan. Los valores en gramos entre paréntesis no sustituyen la medida principal. Las mezclas de verduras usan el promedio del catálogo. Las sustituciones del PDF requieren nueva revisión.","Pendiente de correspondencia o cantidad: Desayuno: 1 taza de fruta; Comida: 150 g de carne de res magra; Comida: 1 fruta"]}'::jsonb from expanded where not exists(select 1 from public.diet_library_items where owner_id is null and provenance->>'label'='Documento aportado · PDF11-D2 · página 3');
end $seed$;
